// Generated by Fern, then extended by hand (listed in src/.fernignore):
// the server's error fields are read from the response as sent.

import type * as core from "../core/index.js";
import { toJson } from "../core/json.js";

export class IbeeError extends Error {
    public readonly statusCode?: number;
    /** The response body as the server sent it (parsed JSON, or text). */
    public readonly body?: unknown;
    public readonly rawResponse?: core.RawResponse;
    /** The server's `error` (or `code`) value. */
    public readonly code?: string;
    /** Billing's reason, from `billing_reason`. */
    public readonly billingReason?: string;
    /** From `admission_context_id`. */
    public readonly admissionContextId?: string;
    /** The server's own message (`message` or `detail`), when it sent one. */
    public readonly serverMessage?: string;
    /** The `x-request-id` response header. */
    public readonly requestId?: string;

    constructor({
        message,
        statusCode,
        body,
        rawResponse,
    }: {
        message?: string;
        statusCode?: number;
        body?: unknown;
        rawResponse?: core.RawResponse;
    }) {
        super(buildMessage({ message, statusCode, body }));
        Object.setPrototypeOf(this, new.target.prototype);
        if (Error.captureStackTrace) {
            Error.captureStackTrace(this, this.constructor);
        }

        this.name = this.constructor.name;
        this.statusCode = statusCode;
        this.body = body;
        this.rawResponse = rawResponse;
        this.code = pick(body, "error", "code");
        this.billingReason = pick(body, "billing_reason");
        this.admissionContextId = pick(body, "admission_context_id");
        this.serverMessage = typeof body === "string" && body !== "" ? body : pick(body, "message", "detail");
        this.requestId = rawResponse?.headers?.get?.("x-request-id") ?? undefined;
    }
}

type Rec = Record<string, unknown>;
const rec = (v: unknown): Rec | undefined => (v && typeof v === "object" && !Array.isArray(v) ? (v as Rec) : undefined);

/** First string value of `keys` at the top level, then inside `detail`, then inside `error`. */
function pick(body: unknown, ...keys: string[]): string | undefined {
    const top = rec(body);
    for (const source of [top, rec(top?.detail), rec(top?.error)]) {
        for (const key of keys) {
            const value = source?.[key];
            if (typeof value === "string" && value !== "") return value;
        }
    }
    return undefined;
}

function buildMessage({
    message,
    statusCode,
    body,
}: {
    message: string | undefined;
    statusCode: number | undefined;
    body: unknown | undefined;
}): string {
    const lines: string[] = [];
    if (message != null) {
        lines.push(message);
    }

    if (statusCode != null) {
        lines.push(`Status code: ${statusCode.toString()}`);
    }

    if (body != null) {
        lines.push(`Body: ${toJson(body, undefined, 2)}`);
    }

    return lines.join("\n");
}
